    pub(crate) fn resolve_global_index(&self, global: &Global) -> usize {
        let raw = self
            .unwrap_stored(global.as_raw())
            .expect("global must originate from this store");
        raw.into_usize()
    }

    /// Returns the stable arena index of the given [`InstanceEntity`].
    ///
    /// # Panics
    ///
    /// If `instance` does not belong to this [`StoreInner`].
    pub(crate) fn resolve_instance_index(&self, instance: &InstanceEntity) -> usize {
        for (key, entity) in self.instances.iter() {
            if core::ptr::eq(entity, instance) {
                return key.into_usize();
            }
        }
